"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";

type NavigationItem = {
  label: string;
  href: string;
  stub?: boolean;
  home?: boolean;
};

const SECTION_IDS = ["hero", "teachers", "formats", "signup", "process"] as const;
const INDIVIDUAL_SECTION_IDS = ["hero", "teachers", "principles", "formats", "process", "signup"] as const;
const MAIN_SECTION_IDS = ["hero", "teacher", "program", "reviews", "signup", "faq", "paths"] as const;

const NAV_ITEMS: NavigationItem[] = [
  { label: "Главная", href: "/", home: true },
  { label: "Наставник", href: "#teachers" },
  { label: "Варианты", href: "#formats" },
  { label: "Запись", href: "#signup" },
  { label: "Уроки", href: "#process" },
];

const INDIVIDUAL_NAV_ITEMS: NavigationItem[] = [
  { label: "Главная", href: "/", home: true },
  { label: "Наставник", href: "#teachers" },
  { label: "Принципы", href: "#principles" },
  { label: "Варианты", href: "#formats" },
  { label: "Обучение", href: "#process" },
  { label: "Запись", href: "#signup" },
];

// Навигация главной: якоря секций страницы.
const MAIN_NAV_ITEMS: NavigationItem[] = [
  { label: "Наставник", href: "#teacher" },
  { label: "Программа", href: "#program" },
  { label: "Отзывы", href: "#reviews" },
  { label: "Инициация", href: "#signup" },
  { label: "FAQ", href: "#faq" },
  { label: "Другой путь", href: "/individual" },
];

export function Header({
  siteTitle,
  headerButtonText,
}: {
  siteTitle?: string;
  headerButtonText?: string;
}) {
  const pathname = usePathname();
  const isMainPage = pathname === "/";
  const isIndividualPage = pathname === "/individual" || pathname.startsWith("/individual/");
  // Состояние сессии: до входа — кнопка «Вход» (модалка), после — «Личный кабинет».
  const { phone, loading: authLoading, openAuth } = useAuth();
  const navItems = isMainPage
    ? MAIN_NAV_ITEMS
    : isIndividualPage
      ? INDIVIDUAL_NAV_ITEMS
      : NAV_ITEMS;
  const sectionIds = isMainPage
    ? MAIN_SECTION_IDS
    : isIndividualPage
      ? INDIVIDUAL_SECTION_IDS
      : SECTION_IDS;

  const [scrolled, setScrolled] = useState(false);
  const [xp, setXp] = useState(0);
  const [menuOpen, setMenuOpen] = useState(false);
  const [isDesktop, setIsDesktop] = useState(true);
  const [activeSection, setActiveSection] = useState<string>("hero");

  useEffect(() => {
    let raf = 0;
    const update = () => {
      raf = 0;
      const scrollY = window.scrollY;
      setScrolled(scrollY > 10);
      const max = document.documentElement.scrollHeight - window.innerHeight;
      setXp(max > 0 ? Math.min(100, Math.round((scrollY / max) * 100)) : 0);

      const offset = 90;
      let current: string = sectionIds[0];
      for (const id of sectionIds) {
        const el = document.getElementById(id);
        if (!el) continue;
        if (el.getBoundingClientRect().top - offset <= 0) {
          current = id;
        }
      }
      setActiveSection(current);
    };
    const onScroll = () => {
      if (raf) return;
      raf = window.requestAnimationFrame(update);
    };

    update();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      if (raf) window.cancelAnimationFrame(raf);
    };
  }, [sectionIds]);

  useEffect(() => {
    const media = window.matchMedia("(min-width: 1025px)");
    const apply = () => setIsDesktop(media.matches);

    apply();
    media.addEventListener("change", apply);
    return () => media.removeEventListener("change", apply);
  }, []);

  useEffect(() => {
    if (!menuOpen) return;

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuOpen(false);
    };

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [menuOpen]);

  useEffect(() => {
    const body = document.body;
    const html = document.documentElement;

    // Блокируем только прокрутку (position:fixed не используем —
    // он ломает переход по якорям после закрытия меню).
    if (menuOpen) {
      body.style.overflow = "hidden";
      html.style.overflow = "hidden";
    } else {
      body.style.overflow = "";
      html.style.overflow = "";
    }

    return () => {
      body.style.overflow = "";
      html.style.overflow = "";
    };
  }, [menuOpen]);

  const handleNavClick = (item: NavigationItem, e: React.MouseEvent) => {
    if (item.stub) {
      e.preventDefault();
      return;
    }
    setMenuOpen(false);
  };

  return (
    <>
    <header className={`site-header${scrolled ? " scrolled" : ""}`}>
      <div className="header-xp" aria-hidden="true">
        <div className="header-xp-fill" style={{ width: `${xp}%` }} />
        <span className="header-xp-label">XP {xp}%</span>
      </div>
      <a href={isMainPage ? "#hero" : isIndividualPage ? "/individual#hero" : "/"} className="site-logo">
        <span className="logo-icon" aria-hidden="true" />
        {siteTitle ?? "District"}
      </a>
      <nav className="main-navigation" aria-label="Основная навигация">
        <ul>
          {navItems.map((item) => (
            <li key={item.label}>
              <a
                href={item.href}
                className={
                  !item.stub && !item.home && activeSection === item.href.replace("#", "")
                    ? "active"
                    : item.stub
                      ? "nav-stub"
                      : item.home
                        ? "nav-home"
                        : undefined
                }
                onClick={(e) => handleNavClick(item, e)}
                aria-disabled={item.stub ? true : undefined}
              >
                {item.label}
              </a>
            </li>
          ))}
        </ul>
      </nav>

      <button
        type="button"
        className={`mobile-menu-button${menuOpen ? " open" : ""}`}
        aria-label={menuOpen ? "Закрыть меню" : "Открыть меню"}
        aria-expanded={menuOpen}
        aria-controls="mobile-menu"
        onClick={() => setMenuOpen((v) => !v)}
      >
        <span className="mobile-menu-icon" aria-hidden="true">
          <span />
          <span />
          <span />
        </span>
      </button>

      {isDesktop && !authLoading ? (
        phone ? (
          <Link href="/cabinet" className="header-account" title={phone} prefetch>
            <span className="header-account-dot" aria-hidden="true" />
            Кабинет курса
          </Link>
        ) : (
          <button type="button" className="header-cta btn btn-gold" onClick={() => openAuth()}>
            Войти на курс
          </button>
        )
      ) : null}
    </header>

    <div
      className={`mobile-menu-overlay${menuOpen ? " open" : ""}`}
      onClick={() => setMenuOpen(false)}
      aria-hidden={!menuOpen}
    >
      <div
        id="mobile-menu"
        className="mobile-menu-panel"
        role="dialog"
        aria-modal="true"
        aria-label="Меню"
        aria-hidden={!menuOpen}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="mobile-menu-top">
          <a
            href={isMainPage ? "#hero" : isIndividualPage ? "/individual#hero" : "/"}
            className="mobile-menu-logo"
            onClick={() => setMenuOpen(false)}
          >
            <span className="logo-icon" aria-hidden="true" />
            {siteTitle ?? "District"}
          </a>
          <button
            type="button"
            className="mobile-menu-close"
            aria-label="Закрыть меню"
            onClick={() => setMenuOpen(false)}
          >
            ×
          </button>
        </div>
        <nav className="mobile-navigation" aria-label="Мобильная навигация">
          {navItems.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className={item.stub ? "nav-stub" : undefined}
              onClick={(e) => handleNavClick(item, e)}
              aria-disabled={item.stub ? true : undefined}
            >
              {item.label}
            </a>
          ))}
        </nav>
        {!authLoading ? (
          phone ? (
            <Link
              href="/cabinet"
              className="mobile-menu-account"
              prefetch
              onClick={() => setMenuOpen(false)}
            >
              <span className="header-account-dot" aria-hidden="true" />
              Кабинет курса
            </Link>
          ) : (
            <button
              type="button"
              className="btn btn-gold mobile-menu-cta"
              onClick={() => {
                setMenuOpen(false);
                openAuth();
              }}
            >
              Войти на курс
            </button>
          )
        ) : null}
      </div>
    </div>
    </>
  );
}
